from solution import does_Contain_B
import inspect


def test_issue_example_given():
    """Example from issue: does_Contain_B(1,7,3) == True."""
    assert does_Contain_B(1, 7, 3) == True  # 7-1=6=2*3 so True


def test_issue_start_equals_target():
    """Sequence starting at A contains A itself."""
    assert does_Contain_B(5, 5, 7) == True  # 5-5=0=0*7 so True


def test_issue_one_step_forward():
    """Sequence starting at A with step C reaches A+C."""
    assert does_Contain_B(2, 5, 3) == True  # 5-2=3=1*3 so True


def test_issue_many_steps_forward():
    """Sequence starting at A reaches A+3*C."""
    assert does_Contain_B(1, 10, 3) == True  # 10-1=9=3*3 so True


def test_issue_not_divisible_gap():
    """Target whose gap from start is not a multiple of step is absent."""
    assert does_Contain_B(1, 8, 3) == False  # 8-1=7 not multiple of 3 so False


def test_issue_target_before_start():
    """Target smaller than start is absent for positive step."""
    assert does_Contain_B(10, 4, 3) == False  # 4<10 so cannot follow 10,13,... so False


def test_issue_just_below_hit():
    """Value just below a reachable value is absent."""
    assert does_Contain_B(1, 6, 3) == False  # 6-1=5 not multiple of 3 so False


def test_issue_large_reachable():
    """Large reachable target is present."""
    assert does_Contain_B(0, 1000000, 1000) == True  # 1000000-0=1000000=1000*1000 so True


def test_issue_step_one_reaches_any_larger():
    """With step 1 any larger target is present."""
    assert does_Contain_B(3, 100, 1) == True  # 100-3=97=97*1 so True


def test_issue_step_larger_than_gap():
    """Target within one step gap but not equal is absent."""
    assert does_Contain_B(3, 5, 10) == False  # 5-3=2 not multiple of 10 so False


def test_issue_negative_start_reachable():
    """Sequence from negative start reaches positive target on step."""
    assert does_Contain_B(-3, 3, 2) == True  # 3-(-3)=6=3*2 so True


def test_contract_returns_bool():
    """Function must return a bool for the documented example."""
    assert isinstance(does_Contain_B(1, 7, 3), bool) == True  # result type is bool so True


def test_contract_takes_three_arguments():
    """Public interface takes three arguments (a, b, c)."""
    assert len(inspect.signature(does_Contain_B).parameters) == 3  # params a,b,c count is 3
